    for r in range(8):
        if board[r] is not None:
            if board[r] == col:
                return False
            if abs(row - r) == abs(col - board[r]):
                return False
    return True

def backtrack(board, row):
    if row == 8:
        return True
    if board[row] is not None:
        return backtrack(board, row + 1)
    for col in range(8):
        if is_valid(board, row, col):
            board[row] = col
            if backtrack(board, row + 1):
                return True
            board[row] = None
    return False

